/**
 * @summary Search places by keyword (school or academy name)
 */
export const getSearchPlacesUrl = (params: SearchPlacesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/search/places?${stringifiedParams}`
    : `/api/search/places`;
};

export const searchPlaces = async (
  params: SearchPlacesParams,
  options?: RequestInit,
): Promise<PlaceSearchResult[]> => {
  return customFetch<PlaceSearchResult[]>(getSearchPlacesUrl(params), {
    ...options,
    method: "GET",
  });
};

